import { sample, expect, test, uniqueName } from "../../fixtures";

test.describe("vendor audit trail", () => {
  test(
    "audit events are listed oldest first with actor and action",
    { tag: "@AUD-01" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads a W-9 for it.
      const member = await apiAs("member");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Audit Vendor"),
          category: "services",
          contact_email: `billing-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% audit trail test w9\n%%EOF\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);

      // Act: request the audit trail. Extraction may complete asynchronously,
      // so poll until the expected three events are present.
      const fetchTrail = async () => {
        const response = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(response.status()).toBe(200);
        return (await response.json()) as {
          items: Array<{
            id: number;
            action: string;
            actor: { id: string; name: string; email: string };
            at: string;
            details: Record<string, unknown>;
          }>;
        };
      };

      let trail = await fetchTrail();
      await expect
        .poll(
          async () => {
            trail = await fetchTrail();
            return trail.items.map((event) => event.action);
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

      // Assert: order and content of each event.
      expect(trail.items.map((event) => event.action)).toEqual([
        "vendor.created",
        "document.uploaded",
        "document.extracted",
      ]);

      for (const event of trail.items) {
        expect(event.actor.email).toBe("member@northwind.test");
        expect(event.actor.name).toBeTruthy();
        expect(event.actor.id).toBeTruthy();
        expect(Number.isNaN(Date.parse(event.at))).toBe(false);
      }

      // Oldest first: timestamps are non-decreasing.
      const times = trail.items.map((event) => Date.parse(event.at));
      for (let i = 1; i < times.length; i++) {
        expect(times[i]).toBeGreaterThanOrEqual(times[i - 1]);
      }
    },
  );
});
